begin;
create temp table assertions(label text);
grant select,insert on assertions to authenticated;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAILED: %',label;end if;insert into assertions values(label);end$$;
create temp table sync_input(data jsonb,takeover jsonb);
insert into sync_input(data) values(__SYNC_MUTATION__::jsonb);
update sync_input set takeover=jsonb_build_object('classId',data->'classId','sessionId',data->'sessionId','deviceId','30000000-0000-4000-8000-000000000088','baseRevision',1,'expectedEpoch',1);
grant select,update on sync_input to authenticated;
insert into auth.users(id,email,is_anonymous) values('10000000-0000-4000-8000-000000000001','writer-a@qa.invalid',false),('10000000-0000-4000-8000-000000000002','writer-b@qa.invalid',false),('10000000-0000-4000-8000-000000000003',null,true);
insert into public.classes(id,owner_id,label,grade,student_count,runtime_mode) select (data->>'classId')::uuid,'10000000-0000-4000-8000-000000000001','7T',7,3,'demo' from sync_input;
insert into public.students(id,class_id,owner_id,attendance_number) select (r->>'id')::uuid,(data->>'classId')::uuid,'10000000-0000-4000-8000-000000000001',(r->>'attendanceNumber')::int from sync_input,jsonb_array_elements(data->'payload'->'roster') r;
insert into pn_private.presentation_sessions(id,class_id,owner_id) select (data->>'sessionId')::uuid,(data->>'classId')::uuid,'10000000-0000-4000-8000-000000000001' from sync_input;
insert into pn_private.presentations(id,session_id,owner_id,board_id,channel_epoch,public_state) select '40000000-0000-4000-8000-000000000001',(data->>'sessionId')::uuid,'10000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000003','40000000-0000-4000-8000-000000000002','{"schemaVersion":1,"mode":"opening","question":1,"taskEpoch":"40000000-0000-4000-8000-000000000003","groups":[]}'::jsonb from sync_input;
select pg_temp.ok(not has_function_privilege('authenticated','public.sync_action_v1(text,jsonb)','EXECUTE'),'old RPC cannot bypass writer wrapper');
set local role authenticated;
set local request.jwt.claims='{"sub":"10000000-0000-4000-8000-000000000001","is_anonymous":false}';
select pg_temp.ok((select public.sync_action('apply',data)->>'status'='accepted' from sync_input),'first writer allocated');
select pg_temp.ok(public.presentation_topic_allowed('pn:state:40000000-0000-4000-8000-000000000001:40000000-0000-4000-8000-000000000002'),'initial board channel permitted');
select pg_temp.ok((select public.sync_action('takeover',takeover||'{"nickname":"PRIVATE"}')->>'error'='INVALID_INPUT' from sync_input),'takeover strict allowlist');
set local request.jwt.claims='{"sub":"10000000-0000-4000-8000-000000000002","is_anonymous":false}';
select pg_temp.ok((select public.sync_action('takeover',takeover)->>'error'='FORBIDDEN' from sync_input),'other teacher takeover forbidden');
set local request.jwt.claims='{"sub":"10000000-0000-4000-8000-000000000003","is_anonymous":true}';
select pg_temp.ok((select public.sync_action('takeover',takeover)->>'error'='FORBIDDEN' from sync_input),'board takeover forbidden');
set local request.jwt.claims='{"sub":"10000000-0000-4000-8000-000000000001","is_anonymous":false}';
select pg_temp.ok((select public.sync_action('takeover',takeover)->>'writerEpoch'='2' from sync_input),'explicit takeover advances epoch');
select pg_temp.ok(not public.presentation_topic_allowed('pn:state:40000000-0000-4000-8000-000000000001:40000000-0000-4000-8000-000000000002'),'takeover invalidates old controller board channel');
select pg_temp.ok((select public.sync_action('takeover',takeover)->>'revision'='2' from sync_input),'lost takeover ACK retry idempotent');
select pg_temp.ok((select public.sync_action('takeover',takeover||'{"deviceId":"30000000-0000-4000-8000-000000000089"}')->>'error'='CONFLICT' from sync_input),'stale concurrent takeover held');
select pg_temp.ok((select public.sync_action('apply',data||'{"eventId":"30000000-0000-4000-8000-000000000090","baseRevision":2}')->>'status'='conflict' from sync_input),'old writer epoch cannot publish even with current revision');
select pg_temp.ok((select public.sync_action('apply',data||'{"eventId":"30000000-0000-4000-8000-000000000091","deviceId":"30000000-0000-4000-8000-000000000088","baseRevision":2,"writerEpoch":2}')->>'status'='accepted' from sync_input),'new writer can publish');
reset role;
select 'PASS '||count(*)||' writer SQL assertions' from assertions;
select 'ok - '||label from assertions;
rollback;
